<!DOCTYPE html>
<html lang="en" data-theme="dark">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Store</title>
  <style>
    :root {
      --bg-color: #0B0C10;
      --text-color: #E5E7EB;
      --accent-color: #F2F0EB;
      --card-bg: #1F2833;
      --border-color: #2D3748;
    }

    html[data-theme="light"] {
      --bg-color: #FFFFFF;
      --text-color: #111827;
      --accent-color: #1F2937;
      --card-bg: #F3F4F6;
      --border-color: #E5E7EB;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      background-color: var(--bg-color);
      color: var(--text-color);
      line-height: 1.5;
      min-height: 100vh;
      overflow-x: hidden;
    }

    .container {
      width: 100%;
      max-width: 1100px;
      margin: 0 auto;
      padding: 0 1rem;
    }

    /* Header */
    .site-header {
      width: 100%;
      border-bottom: 1px solid var(--border-color);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0.75rem 1rem;
      max-width: 1100px;
      margin: 0 auto;
      gap: 1rem;
    }

    .logo {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--accent-color);
      text-decoration: none;
    }

    .site-nav {
      display: flex;
      gap: 1.5rem;
      align-items: center;
    }

    .site-nav a {
      color: var(--text-color);
      text-decoration: none;
      font-size: 0.9rem;
      font-weight: 600;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      transition: color 0.2s;
    }

    .site-nav a:hover {
      color: var(--accent-color);
    }

    #theme-toggle {
      width: 44px;
      height: 44px;
      min-width: 44px;
      min-height: 44px;
      display: flex;
      align-items: center;
      justify-content: center;
      border: 1px solid var(--border-color);
      border-radius: 8px;
      background: transparent;
      color: var(--text-color);
      cursor: pointer;
      font-size: 1.25rem;
    }

    /* Hero */
    .hero {
      padding: 4rem 1rem;
      text-align: center;
    }

    .hero h1 {
      font-size: clamp(2rem, 5vw, 3.5rem);
      margin-bottom: 1rem;
      color: var(--accent-color);
    }

    .hero p {
      font-size: 1.125rem;
      max-width: 600px;
      margin: 0 auto;
      opacity: 0.85;
    }

    /* Promo Strip */
    .promo-strip {
      background-color: var(--card-bg);
      border-top: 1px solid var(--border-color);
      border-bottom: 1px solid var(--border-color);
      padding: 0.75rem 1rem;
      text-align: center;
      font-size: 0.95rem;
      font-weight: 500;
    }

    /* Product Grid */
    .product-section {
      padding: 3rem 1rem 4rem;
    }

    .product-section h2 {
      font-size: 1.75rem;
      margin-bottom: 2rem;
      text-align: center;
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      gap: 1.5rem;
    }

    .product-card {
      background: var(--card-bg);
      border: 1px solid var(--border-color);
      border-radius: 8px;
      padding: 1.5rem;
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
    }

    .product-title {
      font-size: 1.125rem;
      font-weight: 600;
    }

    .product-price {
      font-size: 1rem;
      color: var(--accent-color);
      font-weight: 700;
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="header-inner">
      <a href="#" class="logo">Store</a>
      <nav class="site-nav">
        <a href="#shop">Shop</a>
        <a href="#story">Story</a>
        <a href="#contact">Contact</a>
      </nav>
      <button id="theme-toggle" aria-label="Toggle theme">◐</button>
    </div>
  </header>

  <main>
    <section class="hero container">
      <h1>Modern essentials for refined living</h1>
      <p>Thoughtfully crafted products designed with purpose, quality materials, and minimal environmental impact.</p>
    </section>

    <div class="promo-strip">
      <span>Free worldwide shipping on all orders over $150</span>
    </div>

    <section id="shop" class="product-section container">
      <h2>Featured collection</h2>
      <div class="product-grid">
        <article class="product-card">
          <h3 class="product-title">Classic notebook</h3>
          <p>Linen-bound archival paper for daily notes and sketches.</p>
          <div class="product-price">$28</div>
        </article>
        <article class="product-card">
          <h3 class="product-title">Desk lamp</h3>
          <p>Precision-milled aluminum with warm dimming LED.</p>
          <div class="product-price">$145</div>
        </article>
        <article class="product-card">
          <h3 class="product-title">Ceramic mug</h3>
          <p>Hand-thrown stoneware finished with matte glaze.</p>
          <div class="product-price">$34</div>
        </article>
      </div>
    </section>
  </main>

  <script>
    const themeToggle = document.getElementById('theme-toggle');
    themeToggle.addEventListener('click', () => {
      const currentTheme = document.documentElement.getAttribute('data-theme') || 'dark';
      const nextTheme = currentTheme === 'dark' ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', nextTheme);
    });
  </script>
</body>
</html>
